import json,csv,gzip,sys
from pathlib import Path
root=Path.cwd();p=root/'data/curation/etymology-lab/das-yerava-20260922';sys.path.insert(0,str(root/'data'))
from etymology_assignments import read_assignments
z=json.load(open(p/'proposed-decisions.json'));seen={a['record']['ID'] for a in z['accepted']+z['held']}|{r['Form_ID'] for r in read_assignments()}
rules=[(['Thee','Theeyu'],'Fire','d3266','DEDR3266 gives Tamil tī/tīy and Malayalam tī fire, with Kannada tī fire/burn. Das Thee/Theeyu preserve the corresponding lexical stem in popular spelling; the final y in Theeyu is compatible with the vowel-final stem rather than a separate lexical component.'),(['Neeru'],'Water','d3690','DEDR3690(a) gives Kannada nīr/nīru, Kodagu nīrï and Tamil/Malayalam nīr water. Das Neeru matches this water family. The whole article is the parent despite its displayed tears head; Sanskrit nīra is a comparison, not an established immediate donor.'),(['Nilavu'],'Moon','d3754','DEDR3754 explicitly gives Tamil nilavu/nilā and Malayalam nilāvu/nilā moon and moonlight. Das Nilavu moon preserves the full nominal formation and matching referent.'),(['Palu'],'Milk','d4096','DEDR4096 gives Tamil/Malayalam/Kannada pāl, Kodagu pālï and Telugu pālu milk, within a widely attested Dravidian family. Das Palu is compared without treating its unmarked vowel length as a precise phonemic transcription; the questioned Sanskrit comparison is retained.'),(['Kadu'],'Forest','d1438','DEDR1438 gives Kannada kāḍu, Kodagu kāḍï and Tamil/Malayalam kāṭu forest/jungle; Irula kāḍu has the forest-field meaning. Das Kadu forest preserves the corresponding stop-bearing stem, with no phonemic retroflex mark inferred from popular spelling.'),(['Betta'],'Hill','d5474','DEDR5474 gives Kannada beṭṭa/beṭṭu and Kodagu beṭṭa hill/mountain, alongside Kota veṭm/beṭ and Toda pöṭ. Ravula Betta is compared with this article; close Kannada form and the documented contact context leave local borrowing versus inheritance open.'),(['Male'],'Hill','d4742','DEDR4742 gives Kannada male mountain/forest, Tamil malai hill and Malayalam mala mountain; Kodagu male is mountain-side jungle. Das Male hill matches this southern mountain family. Sanskrit malaya and other compared forms are not immediate donor evidence.'),(['Urang','Urangu'],'Sleep','d707','DEDR707 gives Tamil uṟaṅku, Malayalam uṟaṅṅuka and Irula roṅgu sleep, alongside Kannada oṟaṅgu sleep/recline. Das Urang/Urangu preserve the r and nasal-velar sequence; final-vowel variation is kept in the original records.'),(['Kudi','Kuti'],'Drink','d1654','DEDR1654 gives Tamil kuṭi, Malayalam kuṭikka, Kannada kuḍi and Kodagu kuḍi- drink. Das Kudi/Kuti fit the southern stop alternation; popular spelling does not establish exact phonemes. The article compares Sanskrit kuṭī liquor but provides no donor route for these verbs.'),(['Thinnu'],'Eat','d3263','DEDR3263(a) gives Malayalam tinnuka, Kannada tinnu and Kodagu tinn- eat. Das Thinnu preserves the doubled nasal eating stem; no aspiration is inferred from th. Branches restrict the sense to non-rice food or biting, while the survey simply says Eat.'),(['Nil'],'Stand','d3675','DEDR3675 explicitly gives Tamil nil, Kannada nil/nillu and Kodagu nill- stand. Ravula Nil is a direct stem comparison; the distinct Paniya Ninja needs additional morphological evidence and is not included.')]
n=0
for r in json.load(open(p/'survey-inventory.json')):
 if r['ID'] in seen:continue
 for forms,g,d,ev in rules:
  if r['Form'] in forms and r['Gloss']==g:
   z['accepted'].append(dict(record=r,parent=d,kind='reflex',citation=f'dedr[entry {d[1:]}];'+r['Source'],evidence=ev+' These are whole-article family proposals; inheritance versus local transmission remains subject to review in this multilingual source.',status='pending-review'));seen.add(r['ID']);n+=1;break
 if r['Form']=='Ninja':z['held'].append(dict(record=r,candidate='d3675',reason='Nil/nin standing family is plausible, but Das Paniya Ninja requires same-language evidence for the nj formation; no tense, imperative or derivation is inferred from the bare Stand prompt.'));seen.add(r['ID'])
(p/'proposed-decisions.json').write_text(json.dumps(z,ensure_ascii=False,indent=2)+'\n')
used={a['parent'] for a in z['accepted']};articles={r['Entry_ID']:r for r in csv.DictReader(gzip.open(root/'data/data/dedr/entry-texts-audit.csv.gz','rt')) if r['Entry_ID'] in used and r['Status']!='duplicate-excluded'};(p/'primary-evidence.json').write_text(json.dumps(articles,ensure_ascii=False,indent=2)+'\n');print('added',n)
